/// <summary>
/// CB626_TMSEngineSOPackingSlip
/// Class responsible for the TSIG CSE calculation (no CCR)
/// </summary>
class METTMSShipmentItemGroupUOM_CSE extends METTMSShipmentItemGroupUOM
{
}

Method.Source:
/// <summary>
/// Method for the TSIG quantity UOM
/// </summary>
/// <returns>Shipment UOM CSE</returns>
METShipmentUOM shipmentUOM()
{
    return METConstants::unitCSE;
}

/// <summary>
/// Method to calculate TSIG volume (cube)
/// </summary>
/// <param name = "_quantity">TSIG quantity</param>
/// <returns>TSIG volume (cube)</returns>
METWHSPalletVolume cube(METQty _quantity)
{        
    return isToteCustomer ? lineTmpSum.LineVolume_CaseLines : (lineTmpSum.LineVolume_CaseLines + sumRepackContainersByCommodityCaseVolume);
}

/// <summary>
/// Method to calculate TSIG quantity
/// </summary>
/// <returns>TSIG quantity</returns>
METQty quantity()
{        
    return isToteCustomer ? lineTmpSum.CaseQty_CaseLines : (lineTmpSum.CaseQty_CaseLines + sumRepackContainersByCommodityQty);
}

/// <summary>
/// Method to calculate TSIG weight
/// </summary>
/// <param name = "_quantity">TSIG quantity</param>
/// <returns>TSIG weight</returns>
METQty weight(METQty _quantity)
{
    return isToteCustomer ? lineTmpSum.LineWeight_CaseLines : (lineTmpSum.LineWeight_CaseLines + lineTmpSum.LineWeight_BrokenCaseSecurity + lineTmpSum.LineWeight_BrokenCaseNonSecurity);
}
